bnr.css:
#ksBnr .ukw{position:relative;flex:none;width:390px;height:160px;overflow:hidden;background:#F1E6CF}
#ksBnr .ukw>*{position:absolute;display:block}
#ksBnr .ukw .bnr{left:0;top:0;width:390px;height:160px;object-fit:cover}
#ksBnr .ukw .ukSky,#ksBnr .ukw .ukKs,#ksBnr .ukw .ukSea{left:0;top:0;width:390px;height:160px}
#ksBnr .ukw .ukKs{animation:kbukKs 20s ease-in-out infinite}
#ksBnr .ukw .ukBt{left:166px;top:72px;width:38px;height:29px;transform-origin:50% 90%;animation:kbukBoat 3.6s ease-in-out infinite}
#ksBnr .ukw .ukCr{left:130px;top:94px;width:390px;height:22px;background-size:130px 22px;background-repeat:repeat-x;animation:kbukCrest 9s linear infinite}
#ksBnr .ukw .ukWv{left:-6px;top:-6px;width:182px;height:142px;transform-origin:20px 142px;animation:kbukSurge 5.2s ease-in-out infinite}
#ksBnr .ukw .ukSp{width:50px;height:50px;opacity:0;animation:kbukSpray 5.2s ease-out infinite}
#ksBnr .ukw .ukSp.s1{left:126px;top:8px}
#ksBnr .ukw .ukSp.s2{left:140px;top:30px;animation-delay:-.35s}
#ksBnr .ukw .ukPn{left:0;top:56px;width:780px;height:62px;background-size:390px 62px;background-repeat:repeat-x;animation:kbukFlow 3.472s linear infinite}
#ksBnr .ukw .ukRd{left:0;top:116px;width:780px;height:26px;background-size:390px 26px;background-repeat:repeat-x;animation:kbukFlow 3.1s linear infinite}
#ksBnr .ukw .ukBk{left:0;top:136px;width:780px;height:28px;background-size:390px 28px;background-repeat:repeat-x;animation:kbukFlow 2.542s linear infinite}
#ksBnr .ukw .ukSl{left:364px;top:6px;width:18px;height:18px}
#ksBnr .ukw .ukH{left:190px;top:47px;width:122px;height:84px;overflow:hidden}
#ksBnr .ukw .ukH>i{display:block;width:1220px;height:84px;background:url(ks_b484a6468cece10304293ded8fd0b0da.webp) 0 0/1220px 84px no-repeat;animation:kbukRun .48s steps(10) infinite}
@keyframes kbukRun{100%{transform:translateX(-1220px)}}
@keyframes kbukFlow{0%{transform:translateX(0)}100%{transform:translateX(-390px)}}
@keyframes kbukCrest{0%{transform:translateX(0)}100%{transform:translateX(-130px)}}
@keyframes kbukKs{0%{transform:translateX(-8px)}50%{transform:translateX(10px)}100%{transform:translateX(-8px)}}
@keyframes kbukBoat{0%{transform:translateY(0) rotate(-3deg)}50%{transform:translateY(2px) rotate(3deg)}100%{transform:translateY(0) rotate(-3deg)}}
@keyframes kbukSurge{0%{transform:rotate(-1.5deg) scale(.97,.94)}45%{transform:rotate(1.2deg) scale(1.02,1.05)}60%{transform:rotate(1.6deg) scale(1.03,1.06)}100%{transform:rotate(-1.5deg) scale(.97,.94)}}
@keyframes kbukSpray{0%{opacity:0;transform:translate(0,14px) scale(.6)}42%{opacity:0;transform:translate(0,14px) scale(.6)}52%{opacity:1;transform:translate(6px,-4px) scale(1)}78%{opacity:.8;transform:translate(16px,8px) scale(1.08)}92%{opacity:0;transform:translate(22px,26px) scale(1.1)}100%{opacity:0;transform:translate(22px,26px) scale(1.1)}}
@media (prefers-reduced-motion:reduce){#ksBnr .ukw>:not(.bnr){display:none!important}}
/* 設定の「演出を控えめにする」＝視差効果を減らすと同じ形（16.6） */
#ksBnr.calm .ukw>:not(.bnr){display:none!important}

push.css:
.fxs .uk{--pushA:#F7EDD3;--pushB:#1E3F73;--pushC:#C8402C;--rim:#86A7C9;--rimD:#1E3F73}
.fxs .push.uk{--pr:4px;background:none;border-radius:4px;box-shadow:none;filter:drop-shadow(0 8px 0 rgba(20,34,60,.45)) drop-shadow(0 16px 22px rgba(0,0,0,.35))}
.fxs .push.uk span{font:400 42px/1 "Shippori Antique B1",serif;letter-spacing:.08em;color:#2A2420;text-shadow:0 2px 0 #FFFFFF,0 0 6px rgba(255,255,255,.6)}
.fxs .push.uk::after{inset:-20px;border-radius:14px;border-color:rgba(134,167,201,.95)}
.fxs .uk .ukf{position:absolute;left:-20px;top:-24px;width:230px;height:132px;pointer-events:none;font-style:normal;z-index:-1}
.fxs .uk .ukf svg{display:block;width:230px;height:132px;overflow:visible}
.fxs .uk .ukd{position:absolute;left:-40px;top:-70px;width:280px;height:210px;pointer-events:none;z-index:3;font-style:normal}
.fxs .uk .ukd svg{display:block;width:280px;height:210px;overflow:visible}
.fxs .uk .ukbo{animation:fxukBo 2.4s ease-in-out infinite alternate}
@keyframes fxukBo{from{transform:translateY(-4px) rotate(-6deg)}to{transform:translateY(4px) rotate(6deg)}}
.fxs .uk .uktw{transform-box:fill-box;transform-origin:50% 50%;animation:fxukTw 2.2s ease-in-out infinite}
@keyframes fxukTw{0%,100%{opacity:.25;transform:scale(.6)}50%{opacity:1;transform:scale(1.1)}}
.fxs .pshadow.uk{width:220px}
.fxs .tap.uk{font-family:"Shippori Antique B1",serif;font-weight:400;color:#F7EDD3;letter-spacing:.14em;text-shadow:0 2px 0 #1E3F73,0 0 10px rgba(134,167,201,.6)}
.fxs .pressed.uk{border-radius:4px;background:#F7EDD3;box-shadow:0 0 0 5px #1E3F73,0 7px 0 5px #10223F;animation-name:fxukPress,fxfxH}
@keyframes fxukPress{0%{transform:scale(1)}22%{transform:scale(.9)}45%{transform:scale(1.07)}100%{transform:scale(1.45);opacity:0}}
@media (prefers-reduced-motion:reduce){.fxs .uk .ukbo,.fxs .uk .uktw{animation:none}
.fxs .clips.uk{display:none}}
.fxs .clips.uk{position:absolute;z-index:4;left:50%;top:calc(50% - 40px);width:0;height:0}
